import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import{streetPlan,destinationLabel,exitKind}from '../wayfinding.js';
test('town paving follows walkable collision and reaches every accessible activity',()=>{const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));for(const s of data.scenes.filter(s=>['town','market','hub'].includes(s.key))){const plan=streetPlan(s);assert.ok(plan.size>0);for(const k of plan){const[x,y]=k.split(',').map(Number);assert.equal(s.floor[y][x],'.');}for(const o of [...s.doors,...s.objects.filter(o=>o.xy&&!['patrol','cache','boss'].includes(o.type))])if(s.floor[o.xy[1]]?.[o.xy[0]]==='.')assert.ok(plan.has(o.xy.join(',')),`${s.key}: ${o.type||o.to}`);}});
test('exits expose destinations and distinguish stairs from gates',()=>{assert.equal(destinationLabel({travel_label:'TO / TOWN',to:'town'}),'TOWN');assert.equal(destinationLabel({to:'bell_crypt'}),'Bell Crypt');assert.equal(exitKind({travel_label:'SERVICE HATCH'}),'stairs');assert.equal(exitKind({to:'hub'}),'gate');});
import{environmentFor}from '../environment.js';
test('village, forest, mountain, riverbank, ruins and foundry have distinct art identities',()=>{const samples=[{key:'town',theme:1},{key:'forest',theme:1},{key:'summit',theme:3},{key:'river',theme:0},{key:'field',theme:2},{key:'workshop',theme:0}].map(environmentFor);assert.equal(new Set(samples.map(s=>s.style)).size,6);for(const s of samples){assert.ok(s.ground>=0&&s.ground<8);assert.ok(s.border>=0&&s.border<8);}});
